draw:
var k = 8.99e9;
var q1 = p.q1 * 1e-6, q2 = p.q2 * 1e-6, r = p.sep;
var F = k * Math.abs(q1 * q2) / (r * r);
var repel = (q1 * q2) > 0;

var yc = H * 0.52;
var frac = 0.18 + 0.55 * (r - 0.05) / 0.45;
var s = W * frac;
var x1 = W / 2 - s / 2, x2 = W / 2 + s / 2;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";

// axis
ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(W * 0.04, yc); ctx.lineTo(W * 0.96, yc); ctx.stroke();

// separation bar
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(x1, yc + 34); ctx.lineTo(x2, yc + 34); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.fillText("r = " + r.toFixed(2) + " m", (x1 + x2) / 2, yc + 50);

function blob(x, q, label) {
  var R = 9 + 2.2 * Math.abs(q);
  ctx.fillStyle = q >= 0 ? C.accent : C.figure;
  ctx.beginPath(); ctx.arc(x, yc, R, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = C.paper;
  ctx.fillText(q >= 0 ? "+" : "-", x, yc + 4);
  ctx.fillStyle = C.ink;
  ctx.fillText(label + " = " + q.toFixed(1) + " uC", x, yc - R - 10);
}

function arrow(x, dir, len) {
  ctx.strokeStyle = C.ink;
  ctx.lineWidth = 2;
  var x0 = x + dir * 18, x1b = x + dir * (18 + len);
  ctx.beginPath(); ctx.moveTo(x0, yc); ctx.lineTo(x1b, yc); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x1b, yc);
  ctx.lineTo(x1b - dir * 7, yc - 5);
  ctx.lineTo(x1b - dir * 7, yc + 5);
  ctx.closePath();
  ctx.fillStyle = C.ink; ctx.fill();
}

var Fmax = k * 25e-12 / (0.05 * 0.05);
var len = 12 + 60 * Math.sqrt(Math.min(F / Fmax, 1));
if (F > 0) {
  arrow(x1, repel ? -1 : 1, len);
  arrow(x2, repel ? 1 : -1, len);
}

blob(x1, p.q1, "q1");
blob(x2, p.q2, "q2");

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText(repel ? "like signs: push apart" : "unlike signs: pull together", W * 0.05, H * 0.14);

out.note = "F = " + F.toExponential(3) + " N  on each charge, equal and opposite";

var k = 8.99e9;
var q = p.q * 1e-9, d = p.d, x = p.x;
var r2 = x * x + d * d, r = Math.sqrt(r2);
var E1 = k * q / r2;
var Ex = 2 * E1 * x / r;
var Ey = E1 * d / r;

var ox = W * 0.22, oy = H * 0.5;
var scale = (W * 0.55) / 0.14;
function X(a) { return ox + a * scale; }
function Y(b) { return oy - b * scale; }

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";

// axes
ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(W * 0.06, oy); ctx.lineTo(W * 0.97, oy); ctx.stroke();
ctx.beginPath(); ctx.moveTo(ox, H * 0.08); ctx.lineTo(ox, H * 0.92); ctx.stroke();

// charges
var ys = [d, -d];
for (var i = 0; i < 2; i++) {
  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(X(0), Y(ys[i]), 9, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = C.paper;
  ctx.fillText("+", X(0), Y(ys[i]) + 4);
}
ctx.fillStyle = C.ink;
ctx.textAlign = "right";
ctx.fillText("+q", X(0) - 13, Y(d) + 4);
ctx.fillText("+q", X(0) - 13, Y(-d) + 4);
ctx.textAlign = "center";

// dashed lines from each charge to P
ctx.strokeStyle = C.rule; ctx.setLineDash([3, 4]);
for (i = 0; i < 2; i++) {
  ctx.beginPath(); ctx.moveTo(X(0), Y(ys[i])); ctx.lineTo(X(x), Y(0)); ctx.stroke();
}
ctx.setLineDash([]);

function vec(x0, y0, vx, vy, col) {
  var L = Math.sqrt(vx * vx + vy * vy);
  if (L < 0.5) return;
  var ux = vx / L, uy = vy / L;
  ctx.strokeStyle = col; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x0 + vx, y0 + vy); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x0 + vx, y0 + vy);
  ctx.lineTo(x0 + vx - 8 * ux + 4 * uy, y0 + vy - 8 * uy - 4 * ux);
  ctx.lineTo(x0 + vx - 8 * ux - 4 * uy, y0 + vy - 8 * uy + 4 * ux);
  ctx.closePath(); ctx.fillStyle = col; ctx.fill();
}

var Eref = k * 3e-9 / (0.02 * 0.02);
var g = 70 / Eref;

var px = X(x), py = Y(0);
// individual fields (each points away from its charge)
vec(px, py, E1 * (x / r) * g, E1 * (d / r) * g, C.rule);
vec(px, py, E1 * (x / r) * g, -E1 * (d / r) * g, C.rule);
// resultant
vec(px, py, Ex * g, 0, C.accent);

ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(px, py, 3.5, 0, Math.PI * 2); ctx.fill();
ctx.fillText("P", px, py + 18);
ctx.textAlign = "left";
ctx.fillText("net E", px + Ex * g + 6, py - 6);
ctx.fillText("the two vertical parts cancel", W * 0.06, H * 0.12);

out.note = "each charge gives E1 = " + E1.toFixed(0) + " N/C, vertical part " + Ey.toFixed(0) +
  " N/C cancels, net = " + Ex.toFixed(0) + " N/C along x";

var k = 8.99e9, g = 9.8;
var q = p.q * 1e-9, m = p.m * 1e-3, L = p.L;

// solve sin(th)^2 * tan(th) = k q^2 / (4 L^2 m g) by bisection
var Kc = k * q * q / (4 * L * L * m * g);
var lo = 1e-6, hi = 1.5533, mid = 0;
for (var i = 0; i < 60; i++) {
  mid = 0.5 * (lo + hi);
  var f = Math.sin(mid) * Math.sin(mid) * Math.tan(mid) - Kc;
  if (f > 0) hi = mid; else lo = mid;
}
var th = mid;
var sep = 2 * L * Math.sin(th);

// gentle wobble so the reader sees it is an equilibrium
var wob = 0.05 * th * Math.cos(5 * t) * Math.exp(-(t % 9) * 0.5);
var thA = th + wob, thB = th + wob;

var px = W / 2, py = H * 0.1;
var scale = (H * 0.72) / L;
var ax = px - L * Math.sin(thA) * scale, ay = py + L * Math.cos(thA) * scale;
var bx = px + L * Math.sin(thB) * scale, by = py + L * Math.cos(thB) * scale;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";

// ceiling
ctx.strokeStyle = C.rule; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(W * 0.3, py); ctx.lineTo(W * 0.7, py); ctx.stroke();

// vertical reference
ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px, py + L * scale); ctx.stroke();
ctx.setLineDash([]);

// threads
ctx.strokeStyle = C.rule; ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(ax, ay); ctx.stroke();
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(bx, by); ctx.stroke();

// balls
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(ax, ay, 8, 0, Math.PI * 2); ctx.fill();
ctx.beginPath(); ctx.arc(bx, by, 8, 0, Math.PI * 2); ctx.fill();

// separation marker
ctx.strokeStyle = C.figure; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(ax, ay + 20); ctx.lineTo(bx, by + 20); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("r = " + sep.toFixed(3) + " m", (ax + bx) / 2, ay + 36);

// angle label
ctx.fillText("theta = " + (th * 180 / Math.PI).toFixed(1) + " deg", px + W * 0.20, py + 26);

var F = k * q * q / (sep * sep);
ctx.textAlign = "left";
ctx.fillText("Coulomb push = " + F.toExponential(2) + " N", W * 0.04, H * 0.95);
ctx.fillText("weight = " + (m * g).toExponential(2) + " N", W * 0.04, H * 0.86);

out.note = "separation " + sep.toFixed(4) + " m, angle " + (th * 180 / Math.PI).toFixed(2) +
  " deg, tan(theta) = " + Math.tan(th).toFixed(4);

var k = 8.99e9;
var Lm = 0.60;
var Q1 = 1e-6, Q2 = p.ratio * 1e-6;
var x0 = Lm / (1 + Math.sqrt(Q2 / Q1));

var padL = W * 0.10, padR = W * 0.05;
var yb = H * 0.80, yt = H * 0.12, ym = (yb + yt) / 2;
function X(a) { return padL + (a / Lm) * (W - padL - padR); }

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// axis
ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(padL, ym); ctx.lineTo(W - padR, ym); ctx.stroke();

// curve of net Ex, compressed so it fits
var Eref = k * Q1 / (0.09 * 0.09);
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath();
var started = false;
for (var i = 0; i <= 300; i++) {
  var xx = 0.02 + (Lm - 0.04) * i / 300;
  var E = k * Q1 / (xx * xx) - k * Q2 / ((Lm - xx) * (Lm - xx));
  var u = Math.max(-1, Math.min(1, E / Eref));
  var py = ym - u * (ym - yt) * 0.9;
  if (!started) { ctx.moveTo(X(xx), py); started = true; } else ctx.lineTo(X(xx), py);
}
ctx.stroke();

// zero marker
ctx.strokeStyle = C.figure; ctx.lineWidth = 1.5;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(X(x0), yt); ctx.lineTo(X(x0), yb); ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("net field zero here", X(x0), yt + 12);
ctx.fillText("x = " + x0.toFixed(3) + " m", X(x0), yb + 30);

// charges
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(0), yb, 9, 0, Math.PI * 2); ctx.fill();
ctx.beginPath(); ctx.arc(X(Lm), yb, 9, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.paper;
ctx.fillText("+", X(0), yb + 4);
ctx.fillText("+", X(Lm), yb + 4);
ctx.fillStyle = C.ink;
ctx.fillText("Q1 = 1.0 uC", X(0), yb + 26);
ctx.fillText("Q2 = " + p.ratio.toFixed(1) + " uC", X(Lm), yb + 26);

ctx.textAlign = "left";
ctx.fillText("net Ex  (up = pointing right)", padL + 4, yt);

out.note = "null point at x = " + x0.toFixed(4) + " m from Q1; distance ratio " +
  (x0 / (Lm - x0)).toFixed(3) + " = sqrt(Q1/Q2) = " + Math.sqrt(Q1 / Q2).toFixed(3);
